insert into lessons (module_id, title, slug, content, order_index)
values ((select id from modules where slug = 'combinatorics' and track_id = (select id from tracks where slug = 'amc-8')), 'Counting Principles', 'counting-principles', '[{"type":"meta","author":"Benjamin Qi","frequency":"essential"},{"type":"section","title":"Introduction"},{"type":"text","content":"Most counting problems reduce to two ideas: when do we **multiply**, and when do we **add**? Getting this right is the whole game on the AMC 8."},{"type":"section","title":"The Multiplication Principle"},{"type":"text","content":"If a task splits into a sequence of independent stages, with $a$ choices for the first stage, $b$ for the second, and so on, then the number of ways to complete the whole task is the **product**\n$$a \\times b \\times \\cdots.$$\n\n**Example.** An ice-cream shop has $4$ flavors and $3$ toppings. A scoop-with-topping can be made in\n$$4 \\times 3 = 12$$\nways, because each of the $4$ flavors pairs with each of the $3$ toppings."},{"type":"section","title":"The Addition Principle"},{"type":"text","content":"If a task can be done in one of several **mutually exclusive** ways — cases that never overlap — then the total count is the **sum** of the counts of each case.\n\n**Example.** To travel from $A$ to $B$ you may take one of $3$ bus routes **or** one of $2$ train routes. Since you pick exactly one mode, there are\n$$3 + 2 = 5$$\nways. We add because the bus and train options do not overlap.\n\nThe guiding question: *are the options happening together (multiply) or instead of each other (add)?*"},{"type":"resource","source":"CPH","stars":4,"title":"Counting — Competitive Programmer''s Handbook","description":"A crisp treatment of the multiplication and addition rules with worked examples.","url":"https://cses.fi/book/book.pdf"},{"type":"section","title":"Practice Problems"},{"type":"problem","title":"License plates","source":"AMC 8 (practice)","difficulty":"Easy","statement":"A license plate has $2$ letters (A–Z) followed by $3$ digits (0–9), with repeats allowed. How many different plates are possible?","hint":"Each position is an independent stage — multiply the number of choices.","solution":"There are $26$ choices for each letter and $10$ for each digit:\n$$26 \\times 26 \\times 10 \\times 10 \\times 10 = 676 \\times 1000 = 676{,}000.$$"},{"type":"problem","title":"Paths on a grid","source":"AMC 8 (practice)","difficulty":"Medium","statement":"Starting at the bottom-left corner of a $3 \\times 3$ grid of streets, you walk to the top-right corner moving only **right** or **up**. How many shortest paths are there?","hint":"Every shortest path is a rearrangement of $3$ R''s and $3$ U''s. Count the arrangements.","solution":"A path is a sequence of $3$ rights and $3$ ups, so we choose which $3$ of the $6$ steps are \"right\":\n$$\\binom{6}{3} = \\frac{6!}{3!\\,3!} = 20.$$"},{"type":"problem","title":"At least one even","source":"AMC 8 (practice)","difficulty":"Medium","statement":"A three-digit code uses digits $1$ through $6$, repeats allowed. How many codes contain **at least one** even digit?","hint":"Complementary counting: total minus the codes with **no** even digit.","solution":"There are $6^3 = 216$ codes in all. Codes using only the odd digits $\\{1,3,5\\}$ number $3^3 = 27$. So the codes with at least one even digit total\n$$216 - 27 = 189.$$"}]'::jsonb, 0)
on conflict (module_id, slug) do update set
  title = excluded.title, content = excluded.content, order_index = excluded.order_index;

