insert into lessons (module_id, title, slug, content, order_index)
values ((select id from modules where slug = 'algebra' and track_id = (select id from tracks where slug = 'amc-10-12')), 'Vieta''s Formulas', 'vietas-formulas', '[{"type":"meta","author":"Ryan Chou","frequency":"important"},{"type":"section","title":"Introduction"},{"type":"text","content":"**Vieta''s formulas** relate the coefficients of a polynomial to symmetric functions of its roots. They let you compute sums and products of roots *without ever solving the equation* — a recurring shortcut on the AMC 10/12."},{"type":"section","title":"The Quadratic Case"},{"type":"text","content":"Suppose the quadratic $ax^2 + bx + c$ has roots $r$ and $s$. Then it factors as\n$$a(x - r)(x - s) = ax^2 - a(r+s)x + a\\,rs.$$\nMatching coefficients gives\n$$r + s = -\\frac{b}{a}, \\qquad rs = \\frac{c}{a}.$$"},{"type":"section","title":"The General Formula"},{"type":"text","content":"For a monic polynomial\n$$x^n + c_{n-1}x^{n-1} + \\cdots + c_1 x + c_0$$\nwith roots $r_1, \\dots, r_n$, Vieta''s formulas say the $k$-th **elementary symmetric sum** of the roots equals $(-1)^k c_{n-k}$. The two most useful cases:\n$$\\sum_i r_i = -c_{n-1}, \\qquad \\prod_i r_i = (-1)^n c_0.$$\n\nFor a cubic $x^3 + px^2 + qx + r$ with roots $a,b,c$:\n$$a+b+c = -p, \\quad ab+bc+ca = q, \\quad abc = -r.$$"},{"type":"resource","source":"Art of Problem Solving","stars":5,"title":"Vieta''s Formulas","description":"Statement, proof, and a large bank of contest problems that hinge on Vieta.","url":"https://artofproblemsolving.com/wiki/index.php/Vieta%27s_formulas"},{"type":"section","title":"Practice Problems"},{"type":"problem","title":"Sum of squares of roots","source":"AMC 10/12 (practice)","difficulty":"Easy","statement":"Let $r$ and $s$ be the roots of $x^2 - 7x + 10 = 0$. Find $r^2 + s^2$.","hint":"Use the identity $r^2 + s^2 = (r+s)^2 - 2rs$ together with Vieta.","solution":"Vieta gives $r+s = 7$ and $rs = 10$. Then\n$$r^2 + s^2 = (r+s)^2 - 2rs = 49 - 20 = 29.$$"},{"type":"problem","title":"Recovering a coefficient","source":"AMC 10/12 (practice)","difficulty":"Medium","statement":"The cubic $x^3 - 6x^2 + 11x - k$ has three roots whose product is $6$. What is $k$?","hint":"For $x^3 + px^2 + qx + r$, the product of the roots is $-r$.","solution":"Here the constant term is $-k$, so by Vieta the product of roots is $-(-k) = k$. Given the product is $6$, we get $k = 6$. (Indeed the roots are $1,2,3$.)"},{"type":"problem","title":"A symmetric expression","source":"AMC 10/12 (practice)","difficulty":"Hard","statement":"Let $a,b,c$ be the roots of $x^3 - 3x^2 + 4x - 5 = 0$. Compute\n$$\\frac{1}{a} + \\frac{1}{b} + \\frac{1}{c}.$$","hint":"Write the sum of reciprocals over a common denominator: $\\dfrac{ab+bc+ca}{abc}$.","solution":"By Vieta, $ab+bc+ca = 4$ and $abc = 5$. Therefore\n$$\\frac{1}{a}+\\frac{1}{b}+\\frac{1}{c} = \\frac{ab+bc+ca}{abc} = \\frac{4}{5}.$$"}]'::jsonb, 0)
