insert into lessons (module_id, title, slug, content, order_index)
values ((select id from modules where slug = 'number-theory' and track_id = (select id from tracks where slug = 'amc-10-12')), 'Modular Arithmetic', 'modular-arithmetic', '[{"type":"meta","author":"Andrew Wang","frequency":"important"},{"type":"section","title":"Introduction"},{"type":"text","content":"**Modular arithmetic** is arithmetic with remainders. We write\n$$a \\equiv b \\pmod m$$\nto mean $m \\mid (a - b)$ — that is, $a$ and $b$ leave the same remainder upon division by $m$. This single idea organizes a huge fraction of contest number theory."},{"type":"section","title":"Properties of Congruences"},{"type":"text","content":"Congruences can be added, subtracted, and multiplied just like equations. If $a \\equiv b \\pmod m$ and $c \\equiv d \\pmod m$, then\n$$a + c \\equiv b + d, \\quad a - c \\equiv b - d, \\quad ac \\equiv bd \\pmod m.$$\nIn particular, $a \\equiv b \\pmod m \\implies a^k \\equiv b^k \\pmod m$ for every positive integer $k$.\n\n**Caution:** you may *not* always divide. Cancelling a factor is valid only when that factor is invertible mod $m$ (i.e. coprime to $m$)."},{"type":"section","title":"A Worked Example"},{"type":"text","content":"*What is the remainder when $3^{100}$ is divided by $7$?*\n\nCompute small powers mod $7$:\n$$3^1 \\equiv 3, \\quad 3^2 \\equiv 2, \\quad 3^3 \\equiv 6, \\quad 3^4 \\equiv 4, \\quad 3^5 \\equiv 5, \\quad 3^6 \\equiv 1 \\pmod 7.$$\nThe powers cycle with period $6$. Since $100 = 6\\cdot 16 + 4$,\n$$3^{100} \\equiv 3^{4} \\equiv 4 \\pmod 7.$$\nThe remainder is $4$."},{"type":"resource","source":"AoPS","stars":5,"title":"Introduction to Modular Arithmetic","description":"Definitions, the laws of congruence, and Fermat''s little theorem with contest applications.","url":"https://artofproblemsolving.com/wiki/index.php/Modular_arithmetic"},{"type":"section","title":"Practice Problems"},{"type":"problem","title":"Last digit of a power","source":"AMC 10/12 (practice)","difficulty":"Easy","statement":"What is the units digit of $7^{2024}$?","hint":"The units digit is the value mod $10$. Find the cycle length of $7^k \\pmod{10}$.","solution":"The units digits of $7^1,7^2,7^3,7^4$ are $7,9,3,1$, repeating with period $4$. Since $2024 \\equiv 0 \\pmod 4$, we land on the end of the cycle:\n$$7^{2024} \\equiv 7^4 \\equiv 1 \\pmod{10}.$$\nThe units digit is $1$."},{"type":"problem","title":"A linear congruence","source":"AMC 10/12 (practice)","difficulty":"Medium","statement":"How many integers $n$ with $1 \\le n \\le 100$ satisfy $3n \\equiv 1 \\pmod 7$?","hint":"First solve for $n$ mod $7$ by finding the inverse of $3$ modulo $7$.","solution":"Since $3 \\cdot 5 = 15 \\equiv 1 \\pmod 7$, the inverse of $3$ is $5$, so $n \\equiv 5 \\pmod 7$. The values $n \\in \\{5,12,19,\\dots\\}$ up to $100$ are $5 + 7k$ with $0 \\le k \\le 13$ (since $5 + 7\\cdot 13 = 96$). That is $14$ values."},{"type":"problem","title":"Fermat''s little theorem","source":"AMC 10/12 (practice)","difficulty":"Hard","statement":"Find the remainder when $2^{90}$ is divided by $11$.","hint":"Fermat''s little theorem: if $p$ is prime and $p \\nmid a$, then $a^{p-1} \\equiv 1 \\pmod p$.","solution":"Since $11$ is prime and $11 \\nmid 2$, Fermat gives $2^{10} \\equiv 1 \\pmod{11}$. Then\n$$2^{90} = \\left(2^{10}\\right)^{9} \\equiv 1^{9} = 1 \\pmod{11}.$$\nThe remainder is $1$."}]'::jsonb, 0)
on conflict (module_id, slug) do update set
  title = excluded.title, content = excluded.content, order_index = excluded.order_index;

